using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Threading.Tasks;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 bool CompanionOwnedElsewhere(){var record=LiveCompanion();if(record==null)return false;string owner=Convert.ToString(record["owner"]);if(String.IsNullOrEmpty(owner)||owner==session)return false;SetStatus("Companion is already tabbed in another Workscape. Detach or close its tab there first.");return true;}
 string FindCompanion(){string installed=InstalledExe("companion");if(installed!=null)return installed;try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Jago Suite\Preview\Components\companion")){string path=key==null?null:key.GetValue("Executable") as string;if(path!=null){ValidateStudio("companion",path);return path;}}}catch{}foreach(string file in new[]{Path.Combine(bundle,"Companion","Jago-Companion.exe"),Path.Combine(bundle,"Jago-Companion.exe")})if(File.Exists(file))return file;try{string file=Path.Combine(SharedRoot,"connections.json");if(File.Exists(file)){var all=json.Deserialize<Dictionary<string,string>>(ReadShared(file));string path;if(all.TryGetValue("companion",out path)){ValidateStudio("companion",path);return path;}}}catch{}return null;}
 void SetupCompanionMenu(){var menu=new ToolStripDropDownButton("Companion"){Padding=new Padding(8)};menu.DropDownItems.Add("Open as a tab",null,async(s,e)=>await OpenCompanion(false));menu.DropDownItems.Add("Show narrow side panel",null,async(s,e)=>await OpenCompanion(true));menu.DropDownItems.Add("Float over your work",null,async(s,e)=>await FloatCompanion());menu.DropDownItems.Add("Companion settings…",null,async(s,e)=>{var tab=await OpenCompanion(false);if(tab!=null)Command(tab,"settings");});bar.Items.Add(menu);}
 bool ReuseCompanion(WorkTab tab){return TakeLiveCompanion(tab);}
 async Task<WorkTab> OpenCompanion(bool side){var previous=tabs.SelectedTab;if(previous!=home&&Current()!=null&&Current().studio=="companion"){var other=items.FirstOrDefault(t=>t.studio!="companion");previous=other==null?home:other.page;};var tab=await EnsureCompanion();if(tab==null)return null;Command(tab,"compact",new Dictionary<string,object>{{"enabled",side}});if(side)await DockCompanion(tab,previous);else{CloseCompanionDock();tabs.SelectedTab=tab.page;await SelectTab();}return tab;}
 async Task<bool> ReleaseCompanion(WorkTab tab){string ack=Path.Combine(tab.folder,"released.json");if(File.Exists(ack))File.Delete(ack);Command(tab,"close");for(int i=0;i<120;i++){if(tab.process.HasExited||File.Exists(ack))return true;await Task.Delay(50);}SetStatus("Companion is still saving. Keep its tab open until it finishes.");LinkKeyboard(tab);return false;}
 async Task CompanionTest(){try{var tab=await OpenCompanion(false);if(tab==null||!tab.attached)throw new Exception("Companion did not attach");Command(tab,"test-status");await Task.Delay(1000);var result=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"test-result.json")));if(!Convert.ToBoolean(result["tabbed"])||GetParent(new IntPtr(Convert.ToInt64(result["handle"])))!=tab.panel.Handle)throw new Exception("Companion is not a real tab");await CaptureTab(tab);if(!ReadShared(Path.Combine(tab.folder,"snapshot.json")).Contains("jago-companion-note"))throw new Exception("Note snapshot absent");var primary=new WorkTab{id=Guid.NewGuid().ToString(),studio="library",folder=Path.Combine(root,"FakeStudio"),title="Test studio",page=new TabPage("Test studio"),panel=new Panel{Dock=DockStyle.Fill},process=Process.GetCurrentProcess()};Directory.CreateDirectory(primary.folder);primary.page.Controls.Add(primary.panel);primary.panel.Controls.Add(new Label{Text="Studio surface",Dock=DockStyle.Fill});items.Add(primary);tabs.TabPages.Add(primary.page);tabs.SelectedTab=primary.page;await OpenCompanion(true);await Task.Delay(1000);if(companionSide==null||companionSide.Panel2.Width<300||companionSide.Panel2.Width>430||tab.panel.Parent!=companionSide.Panel2)throw new Exception("Narrow sidebar layout failed");CloseCompanionDock();items.Remove(primary);tabs.TabPages.Remove(primary.page);primary.page.Dispose();tabs.SelectedTab=tab.page;await SelectTab();await Detach();await Task.Delay(1000);if(tab.process.HasExited)throw new Exception("Detach closed Companion");await Reattach(tab);await CloseChild(tab);if(tab.process.HasExited)throw new Exception("Closing tab stopped tray Companion");Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks=new[]{"native Companion attaches as tab","editable note snapshot saved","narrow adjustable side panel","detach and reattach preserve process","closing tab returns to tray"}}));if(WorkspaceProgram.Test!=null)tab.process.Kill();items.Remove(tab);tabs.TabPages.Remove(tab.page);}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString()}));}allowClose=true;Close();}
}
